import { useCallback,useEffect,useState,type ReactNode } from 'react';
import { Activity,Banknote,Boxes,BriefcaseBusiness,CalendarClock,ChevronDown,ClipboardCheck,FileCheck2,FileClock,FileSpreadsheet,FileText,Factory,Mail,Package,RefreshCw,ShieldAlert,ShieldCheck,Upload,Users,Wallet,X } from 'lucide-react';
import * as XLSX from 'xlsx';
import { today,actionRecord,api,createRecord,formatDate,formatVnd,getRecords,messageOf,statusLabel,updateRecord,type RecordRow } from './api';
