type Row = RecordRow & Record<string, any>;
type Column = { key: string; label: string; format?: 'money' | 'date' | 'status' | 'classification' };
type Action = { label: string; action: string; variant?: 'primary' | 'secondary' | 'ghost' };
type ResourceProps = { entity: string; title: string; description: string; icon: ReactNode; columns: Column[]; fields: FieldDef[]; actions?: (row: Row, role: string) => Action[]; toolbar?: ReactNode; rowExtra?: (row: Row, reload: () => Promise<void>) => ReactNode; emptyDescription?: string; fixedType?: 'INPUT' | 'OUTPUT' };

const classificationNames: Record<string, string> = { BUSINESS_INCOME: 'Thu kinh doanh', BUSINESS_EXPENSE: 'Chi kinh doanh', PERSONAL: 'Cá nhân', INTERNAL_TRANSFER: 'Chuyển nội bộ', OWNER_FUNDING: 'Chủ bổ sung vốn', OWNER_DRAW: 'Chủ rút tiền', UNCLASSIFIED: 'Chưa phân loại' };
const classificationOptions = Object.entries(classificationNames).map(([value, label]) => ({ value, label }));
const directionOptions = [{ value: 'INCOME', label: 'Thu tiền' }, { value: 'EXPENSE', label: 'Chi tiền' }];
function useRows(entity: string) {
  const [rows, setRows] = useState<Row[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const reload = useCallback(async () => { setLoading(true); setError(''); try { setRows(await getRecords<Row>(entity)); } catch (reason) { setError(messageOf(reason)); } finally { setLoading(false); } }, [entity]);
  useEffect(() => { void reload(); const changed = () => { void reload(); }; window.addEventListener('fintax:records-changed', changed); return () => window.removeEventListener('fintax:records-changed', changed); }, [reload]);
  const hasPendingOdooSync = rows.some((row) => ['PENDING_ODOO', 'PENDING', 'PROCESSING'].includes(String(row.syncStatus || '')));
  useEffect(() => {
    if (!hasPendingOdooSync) return;
    const timer = window.setInterval(() => { void getRecords<Row>(entity).then(setRows).catch(() => undefined); }, 2500);
    return () => window.clearInterval(timer);
  }, [entity, hasPendingOdooSync]);
  return { rows, setRows, loading, error, reload };
}

function ResourcePage({ entity, title, columns, fields, actions, toolbar, rowExtra, fixedType }: ResourceProps) {
  const { rows, loading, error, reload } = useRows(entity);
  const [params,setParams] = useSearchParams();
  const [openedView, setOpenedView] = useState('');
  const [cancelTarget, setCancelTarget] = useState<Row | null>(null), [paymentInvoice, setPaymentInvoice] = useState<Row | null>(null), [actionDialog, setActionDialog] = useState<{ row: Row; item: Action } | null>(null);
  const [formLookups, setFormLookups] = useState<Record<string, Row[]>>({});
  useEffect(() => { const sources: Record<string,string[]> = { reconciliations:['invoices','payments'], 'stock-movements':['materials','production-orders'], 'production-orders':['workshop-members','products','boms'] }; const needed = sources[entity]; if (needed) void Promise.all(needed.map(async (name) => [name,await getRecords<Row>(name)] as const)).then((rows) => setFormLookups(Object.fromEntries(rows))).catch(() => undefined); }, [entity]);
  const [openingPartner,setOpeningPartner]=useState<Row|null>(null);
  const [allocateInvoice, setAllocateInvoice] = useState<string | null>(null);
  const [modal, setModal] = useState(params.get('new') === '1'), [editing, setEditing] = useState<Row | null>(null), [detail, setDetail] = useState<Row | null>(null), [busy, setBusy] = useState(false);
  const [quoteRules, setQuoteRules] = useState<Row[]>([]);
  useEffect(() => { if (entity === 'quotations') void getRecords<Row>('tax-rules').then(setQuoteRules).catch(() => undefined); }, [entity]);
  const sourceFields = fields.map((field): FieldDef => { const source = field.name === 'productId' ? 'products' : field.name === 'bomId' ? 'boms' : field.name === 'invoiceId' ? 'invoices' : field.name === 'paymentId' ? 'payments' : field.name === 'productionOrderId' ? 'production-orders' : field.name === 'materialName' || field.name === 'materialId' ? 'materials' : field.name === 'assignedTo' ? 'workshop-members' : ''; return source && formLookups[source] ? { ...field, name: source === 'materials' ? 'materialId' : field.name, type: 'select', label: source === 'products' ? 'Sản phẩm' : source === 'boms' ? 'Định mức' : source === 'invoices' ? 'Hóa đơn' : source === 'payments' ? 'Phiếu thanh toán' : source === 'production-orders' ? 'Lệnh sản xuất' : source === 'workshop-members' ? 'Người phụ trách' : 'Vật tư', options: formLookups[source].map((row) => ({ value: row.id, label: `${row.code || row.name || row.productName} ${row.counterparty ? `· ${row.counterparty}` : ''}` })) } : field; });
  const formFields: FieldDef[] = entity === 'quotations' ? [...fields.filter((field) => !['taxAmount', 'taxRate'].includes(field.name)), { name: 'taxRuleId', label: 'Quy tắc thuế', type: 'select', options: quoteRules.map((rule) => ({ value: rule.id, label: `${rule.name} · ${rule.taxRate}%` })) }, { name: 'taxRate', label: 'Thuế suất (%)', type: 'number', min: 0, max: 100 }, { name: 'subtotal', label: 'Tiền hàng tự tính (₫)', type: 'number', readOnly: true }, { name: 'taxAmount', label: 'Thuế tự tính (₫)', type: 'number', readOnly: true }, { name: 'total', label: 'Tổng tiền tự tính (₫)', type: 'number', readOnly: true }] : sourceFields;
  const quotePreview = entity === 'quotations' ? (values: Record<string, string>) => { const cost = (Number(values.materialCost || 0) + Number(values.laborHours || 0) * Number(values.laborRate || 0) + Number(values.machineCost || 0)) * (1 + Number(values.wasteRate || 0) / 100); const margin = Number(values.marginRate || 0) / 100; const price = Number(values.unitPrice || 0) || Math.round(cost / (1 - margin)); const subtotal = Math.round(Number(values.quantity || 0) * price); const taxRate = Number(quoteRules.find((rule) => rule.id === values.taxRuleId)?.taxRate ?? values.taxRate ?? 0); const taxAmount = Math.round(subtotal * taxRate / 100); return { ...values, subtotal: String(subtotal), taxRate: String(taxRate), taxAmount: String(taxAmount), total: String(subtotal + taxAmount) }; } : undefined;
  const toast = useToast(), { user } = useAuth();
  const can = (action: string) => user?.permissions?.actions === '*' || Boolean(user?.permissions?.actions?.includes(action));
  const canEdit = can('update') && user?.role !== 'WORKSHOP' && !(entity === 'tax-rules' && user?.role !== 'OWNER');
  const creating = (entity === 'stock-movements' ? can('create') || can('record-movement') : can('create') && !['WORKSHOP','WAREHOUSE'].includes(user?.role || '')) && !(entity === 'tax-rules' && user?.role !== 'OWNER');
  const filtered = fixedType ? rows.filter((row) => row.direction === fixedType || row.type === fixedType) : rows;
  useEffect(() => { const view = params.get('view'); if (view && view !== openedView && !loading) { const match = rows.find((row) => (!fixedType || row.direction === fixedType || row.type === fixedType) && (row.code === view || row.id === view)); if (match) { setDetail(match); setOpenedView(view); } } }, [params,rows,loading,openedView]);
  const save = async (value: Record<string, unknown>) => {
    setBusy(true);
    try { if (editing) await updateRecord(entity, editing.id, value); else await createRecord(entity, { ...value, ...(fixedType ? { type: fixedType, direction: fixedType } : {}) }); setModal(false); setEditing(null); toast('Đã lưu chứng từ.'); await reload(); window.dispatchEvent(new Event('fintax:records-changed')); }
    catch (error) { throw new Error(messageOf(error)); } finally { setBusy(false); }
  };
  const perform = async (row: Row, item: Action, note = '') => {
    const result = await actionRecord<Row>(entity,row.id,item.action,{ note }); await reload(); if (item.action === 'revise') { setDetail(null); setEditing(result); } toast(item.action === 'revise' ? 'Đã tạo phiên bản mới.' : 'Đã cập nhật chứng từ.'); window.dispatchEvent(new Event('fintax:records-changed'));
  };
  const run = async (row: Row,item: Action) => { if (['reject','unlock','reopen','lock','complete'].includes(item.action)) { setActionDialog({ row,item }); return; } try { await perform(row,item); } catch (error) { toast(messageOf(error),'error'); } };
  const workflow = (row: Row) => actions?.(row,user?.role || '').filter((item) => can(item.action)).map((item) => <Button key={item.action} variant={item.variant || 'ghost'} className="px-2 py-1.5 text-[11px]" onClick={() => void run(row,item)}>{item.label}</Button>);
  const cancellable = (row: Row) => user?.role === 'OWNER' && !['CANCELLED','VOID','LOCKED'].includes(row.status || '') && !['tax-periods','payment-allocations','labor-logs'].includes(entity);
  const controls = (row: Row) => <><Button variant="ghost" className="px-2 py-1.5 text-[11px]" onClick={() => setDetail(row)}><Eye size={13}/>Chi tiết</Button>{rowExtra?.(row,reload)}{user?.role==='OWNER'&&['customers','suppliers'].includes(entity)&&<Button variant="secondary" className="px-2 py-1.5 text-[11px]" onClick={()=>setOpeningPartner(row)}>Đầu kỳ</Button>}{canEdit && !['CANCELLED','VOID','LOCKED'].includes(row.status || '') && !(entity === 'reconciliations' && row.status === 'MATCHED') && !['transactions','payments','payment-allocations','stock-movements','labor-logs'].includes(entity) && <Button variant="ghost" className="px-2 py-1.5 text-[11px]" onClick={() => setEditing(row)}><Pencil size={13}/>Sửa</Button>}{workflow(row)}{cancellable(row) && <Button variant="danger" className="px-2 py-1.5 text-[11px]" onClick={() => setCancelTarget(row)}><Trash2 size={13}/>Hủy</Button>}</>;
  const quoteInitial = editing && entity === 'quotations' ? { ...editing, wasteRate: Number(editing.wasteRate || 0) < 1 ? Number(editing.wasteRate || 0)*100 : editing.wasteRate, marginRate: Number(editing.marginRate || 0) < 1 ? Number(editing.marginRate || 0)*100 : editing.marginRate } : editing;
  return <><PageHeader title={title} action={<div className="flex flex-wrap gap-2">{toolbar}<Button variant="secondary" className="px-3 py-2 text-xs" onClick={() => void reload()}><RefreshCw size={14}/>Làm mới</Button>{creating && <AddButton onClick={() => setModal(true)} label="Thêm mới"/>}</div>}/><Card>{error ? <p className="p-5 text-red-700">{error}</p> : loading ? <p className="p-8 text-muted">Đang tải chứng từ…</p> : <DataTable title={title} rows={filtered} columns={columns} controls={controls}/>}</Card>
  {(modal && creating || editing) && (entity === 'invoices' ? <InvoiceModal initial={editing || {}} direction={fixedType || (editing?.direction === 'INPUT' ? 'INPUT' : 'OUTPUT')} onClose={() => { setModal(false); setEditing(null); }} onSubmit={save}/> : entity==='boms' ? <BomModal initial={editing||{}} onClose={()=>{setModal(false);setEditing(null);}} onSubmit={save}/> : entity==='quotations' ? <QuotationModal initial={editing||{}} onClose={()=>{setModal(false);setEditing(null);}} onSubmit={save}/> : entity==='stock-movements' ? <StockMovementModal onClose={()=>setModal(false)} onSubmit={save}/> : <RecordModal key={editing?.id || 'new'} title={editing ? `Sửa ${title.toLocaleLowerCase('vi')}` : title} fields={formFields} derive={quotePreview} initial={quoteInitial || { date:today(),status:['customers','suppliers','materials','products','cash-accounts','branches','classification-rules'].includes(entity)?'ACTIVE':entity==='tax-rules'?'REVIEW_REQUIRED':'DRAFT',trackInventory:'true',direction:params.get('direction') || '' }} onClose={() => { setModal(false); setEditing(null); }} onSubmit={save} busy={busy}/>)}
  {detail && <DocumentDetail entity={entity} record={detail} onClose={() => { setDetail(null); if (params.has('view')) { const next = new URLSearchParams(params); next.delete('view'); setParams(next,{replace:true}); } }} onChanged={reload} canCancel={cancellable(detail)} canCode={entity==='invoices' && detail.direction === 'OUTPUT' && !detail.mockTaxCode && can('simulate-code')} canUnallocate={can('unallocate')} onPayment={entity === 'invoices' && can('create') ? () => { setPaymentInvoice(detail); setDetail(null); } : undefined} onAllocate={can('create') && ['invoices','payments'].includes(entity) ? () => { setAllocateInvoice(detail.id); setDetail(null); } : undefined} onCancel={() => setCancelTarget(detail)} onCode={() => perform(detail,{ action:'simulate-code',label:'Cấp mã CQT' })} actions={<>{entity !== 'invoices' && workflow(detail)}{entity === 'production-orders' && <span onClick={() => setDetail(null)} className="contents">{rowExtra?.(detail,reload)}</span>}</>}/>}
  {openingPartner&&<OpeningBalanceModal partner={openingPartner} partnerType={entity==='customers'?'CUSTOMER':'SUPPLIER'} onClose={()=>setOpeningPartner(null)} onSaved={reload}/>}
  {allocateInvoice && <AllocationModal invoiceId={entity === 'invoices' ? allocateInvoice : undefined} paymentId={entity === 'payments' ? allocateInvoice : undefined} onClose={() => setAllocateInvoice(null)} onSaved={reload}/>}
  {paymentInvoice && <PaymentFromInvoice invoice={paymentInvoice} onClose={() => setPaymentInvoice(null)} onSaved={reload}/>}
  {cancelTarget && <CancelDocument entity={entity} record={cancelTarget} onClose={() => setCancelTarget(null)} onSaved={async () => { setDetail(null); await reload(); window.dispatchEvent(new Event('fintax:records-changed')); toast('Đã hủy chứng từ.'); }}/>}
  {actionDialog && <RecordModal title={actionDialog.item.label} fields={[{ name:'note',label:actionDialog.item.action === 'reject' ? 'Lý do từ chối' : actionDialog.item.action === 'lock' ? 'Ghi chú khóa sổ' : actionDialog.item.action === 'complete' ? 'Ghi chú / lý do chênh lệch định mức' : 'Lý do mở lại',type:'textarea',required:!['lock','complete'].includes(actionDialog.item.action),wide:true }]} onClose={() => setActionDialog(null)} onSubmit={async (value) => { await perform(actionDialog.row,actionDialog.item,String(value.note || '')); setActionDialog(null); }}/>}
  </>;
}

function AllocationPanel({ invoiceId, paymentId, onChanged }: { invoiceId?: string; paymentId?: string; onChanged?: () => Promise<void> }) {
  const { rows, reload } = useRows('payment-allocations'), { user } = useAuth(), toast = useToast();
  const [target,setTarget] = useState<Row | null>(null);
  const unallocate = async (reason: string) => { if (!target) return; await actionRecord('payment-allocations',target.id,'unallocate',{ reason }); await reload(); await onChanged?.(); setTarget(null); window.dispatchEvent(new Event('fintax:records-changed')); toast('Đã gỡ phân bổ và cập nhật công nợ.'); };
  return <div className="mt-5 border-t border-line pt-4"><h3 className="font-semibold">Phân bổ thanh toán</h3><DataTable title="Phân bổ thanh toán" rows={rows.filter((row) => (!invoiceId || row.invoiceId === invoiceId) && (!paymentId || row.paymentId === paymentId))} columns={[{ key: 'invoiceCode', label: 'Hóa đơn' }, { key: 'paymentCode', label: 'Phiếu thu/chi' }, { key: 'allocatedAmount', label: 'Tiền phân bổ', format: 'money' }, { key: 'discountAmount', label: 'Chiết khấu', format: 'money' }, { key: 'roundingAdjustment', label: 'Làm tròn', format: 'money' }, { key: 'bankFeeAmount', label: 'Phí NH chi riêng', format: 'money' }, { key: 'status', label: 'Trạng thái', format: 'status' }]} controls={(row) => ['OWNER', 'ACCOUNTANT'].includes(user?.role || '') && !['CANCELLED', 'UNALLOCATED'].includes(row.status) ? <Button variant="danger" onClick={() => setTarget(row)}>Gỡ phân bổ</Button> : null}/>{target && <RecordModal title={`Gỡ phân bổ · ${target.paymentCode}`} fields={[{ name:"reason",label:"Lý do gỡ phân bổ",type:"textarea",required:true,wide:true }]} onClose={() => setTarget(null)} onSubmit={async (value) => unallocate(String(value.reason))}/>}</div>;
}

export function TransactionsPage() {
  const [searchParams] = useSearchParams();
  const [importOpen, setImportOpen] = useState(searchParams.get('import') === '1');
  const { user } = useAuth();
  const canCreate = !user?.permissions || user.permissions.actions === '*' || user.permissions.actions.includes('create');
  const canClassify = !user?.permissions || user.permissions.actions === '*' || user.permissions.actions.includes('classify');
  const [preview, setPreview] = useState<any>(null); const [file, setFile] = useState<File | null>(null); const [importBusy, setImportBusy] = useState(false); const [transferModal, setTransferModal] = useState(false); const [transferBusy, setTransferBusy] = useState(false); const [importAccountId, setImportAccountId] = useState(''); const [includeDuplicates, setIncludeDuplicates] = useState(false); const accounts = useRows('cash-accounts'); const toast = useToast();
  const businessAccounts = accounts.rows.filter((account) => account.ownerScope !== 'PERSONAL');
  const accountOptions = accounts.rows.map((account) => ({ value: account.id, label: `${account.name} · ${formatVnd(account.balance)}` }));
  useEffect(() => { if (!importAccountId && businessAccounts.length) setImportAccountId(businessAccounts[0].id); }, [businessAccounts, importAccountId]);
  const submitImport = async () => {
    if (!file) { toast('Chọn file CSV hoặc Excel trước.', 'info'); return; }
    const form = new FormData(); form.append('file', file); setImportBusy(true);
    try { const { data } = await api.post('/import/transactions/preview', form); setPreview(data); }
    catch (error) { toast(messageOf(error), 'error'); }
    finally { setImportBusy(false); }
  };
  const commitImport = async () => {
    setImportBusy(true);
    if (!importAccountId) { toast('Chọn tài khoản sẽ nhận các giao dịch sao kê.', 'info'); return; }
    try { const { data } = await api.post(`/import/transactions/${preview.importId}/commit`, { accountId: importAccountId, includeDuplicates }); toast(`Đã nhập ${data.createdCount} giao dịch; bỏ qua ${data.skippedDuplicates} dòng trùng và ${data.skippedInvalid} dòng lỗi.`); setPreview(null); setFile(null); window.location.reload(); }
    catch (error) { toast(messageOf(error), 'error'); }
    finally { setImportBusy(false); }
  };
  const transferFields: FieldDef[] = [{ name: 'date', label: 'Ngày chuyển', type: 'date', required: true }, { name: 'fromAccountId', label: 'Từ tài khoản', type: 'select', required: true, options: accountOptions }, { name: 'toAccountId', label: 'Đến tài khoản', type: 'select', required: true, options: accountOptions }, { name: 'amount', label: 'Số tiền (₫)', type: 'number', required: true, min: 1 }, { name: 'note', label: 'Nội dung', placeholder: 'Chuyển tiền nội bộ' }];
  const transferMoney = async (value: Record<string, unknown>) => { setTransferBusy(true); try { if (value.fromAccountId === value.toAccountId) throw new Error('Hãy chọn hai tài khoản khác nhau.'); await api.post('/transfers', value); toast('Đã ghi nhận cặp chuyển tiền nội bộ cân bằng.'); setTransferModal(false); window.location.reload(); } catch (error) { throw new Error(messageOf(error)); } finally { setTransferBusy(false); } };
  const toolbar = <>{canCreate && <><Button variant="secondary" onClick={() => setTransferModal(true)}><RefreshCw size={15} />Chuyển nội bộ</Button><label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border border-line bg-white px-3.5 py-2.5 text-sm font-medium text-ink hover:bg-gray-50"><Upload size={15} />Import sao kê<input type="file" accept=".csv,.xlsx,.xls" className="hidden" onChange={(e) => setFile(e.target.files?.[0] || null)} /></label></>}</>;
  return <>{importOpen && <Card className="mb-5 border-brand-200 p-5"><div className="flex items-center justify-between"><h2 className="flex items-center gap-2 font-bold"><Upload size={17}/>Nhập sao kê ngân hàng</h2><Button variant="ghost" onClick={() => setImportOpen(false)}>Đóng</Button></div><p className="mt-2 text-xs text-muted">Chọn file CSV hoặc Excel. Kiểm tra dòng trùng trước khi ghi sổ.</p><input aria-label="Chọn file sao kê" type="file" accept=".csv,.xlsx,.xls" className="mt-4 block text-sm" onChange={(event) => setFile(event.target.files?.[0] || null)}/></Card>}<ResourcePage entity="transactions" title="Sổ quỹ & dòng tiền" description="Thu chi, sao kê và phân loại riêng dòng tiền kinh doanh với cá nhân." icon={<Wallet size={18} />} columns={[{ key: 'date', label: 'Ngày', format: 'date' }, { key: 'description', label: 'Nội dung' }, { key: 'counterparty', label: 'Đối tượng' }, { key: 'accountName', label: 'Tài khoản' }, { key: 'direction', label: 'Loại' }, { key: 'amount', label: 'Số tiền', format: 'money' }, { key: 'classification', label: 'Phân loại', format: 'classification' }]} fields={[{ name: 'date', label: 'Ngày giao dịch', type: 'date', required: true }, { name: 'description', label: 'Nội dung', required: true }, { name: 'counterparty', label: 'Đối tượng' }, { name: 'amount', label: 'Số tiền (₫)', type: 'number', required: true, min: 1 }, { name: 'direction', label: 'Loại giao dịch', type: 'select', required: true, options: directionOptions }, { name: 'classification', label: 'Nhóm phân loại', type: 'select', required: true, options: classificationOptions }, { name: 'accountId', label: 'Tài khoản tiền', type: 'select', required: true, options: accountOptions, wide: true }, { name: 'category', label: 'Danh mục' }, { name: 'descriptionNote', label: 'Ghi chú', type: 'textarea', wide: true }]} toolbar={toolbar} actions={(row, role) => role === 'WORKSHOP' ? [] : [{ label: row.classification === 'UNCLASSIFIED' ? 'Phân loại' : 'Sửa nhóm', action: 'classify' }]} rowExtra={(row, reload) => canClassify ? <select aria-label="Phân loại giao dịch" title="Phân loại nhanh" value={row.classification || 'UNCLASSIFIED'} onChange={async (event) => { try { await actionRecord('transactions', row.id, 'classify', { classification: event.target.value }); toast('Đã cập nhật phân loại.'); await reload(); } catch (error) { toast(messageOf(error), 'error'); } }} className="max-w-36 rounded-lg border border-line bg-white px-2 py-1.5 text-[11px] text-muted"><option value="UNCLASSIFIED">Chưa phân loại</option>{classificationOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select> : null} />
    {file && <div className="fixed bottom-5 left-5 z-40 flex items-center gap-3 rounded-2xl border border-line bg-white p-3 shadow-xl"><FileSpreadsheet size={18} className="text-emerald-700" /><div className="max-w-48 truncate text-xs">{file.name}</div><Button onClick={() => void submitImport()} disabled={importBusy}>{importBusy ? 'Đang đọc…' : 'Xem trước'}</Button><button onClick={() => setFile(null)} className="text-muted"><X size={16} /></button></div>}
    {preview && <div className="fixed inset-0 z-50 flex items-end justify-center bg-ink/40 p-0 backdrop-blur-sm sm:items-center sm:p-5"><div className="max-h-[90vh] w-full max-w-4xl overflow-hidden rounded-t-3xl bg-white shadow-2xl sm:rounded-3xl"><div className="flex items-center justify-between border-b border-line p-5"><div><p className="text-xs font-semibold uppercase tracking-wider text-brand-600">Kiểm tra trước khi nhập</p><h2 className="mt-1 font-semibold">{preview.fileName}</h2><p className="mt-1 text-xs text-muted">{preview.total} dòng · {preview.duplicateCount} trùng · {preview.errorCount} dòng lỗi</p></div><button onClick={() => setPreview(null)}><X size={20} /></button></div><div className="max-h-[55vh] overflow-auto"><table className="w-full min-w-[760px] text-left text-xs"><thead className="sticky top-0 bg-gray-50"><tr>{['Dòng', 'Ngày', 'Nội dung', 'Số tiền', 'Loại', 'Phân loại gợi ý', 'Kết quả'].map((name) => <th key={name} className="px-4 py-3 font-semibold text-muted">{name}</th>)}</tr></thead><tbody className="divide-y divide-line">{preview.rows.map((row: any) => <tr key={row.rowNumber} className={row.duplicate || row.errors.length ? 'bg-amber-50/50' : ''}><td className="px-4 py-3">{row.rowNumber}</td><td className="px-4 py-3">{row.date || '—'}</td><td className="max-w-60 truncate px-4 py-3">{row.description || '—'}</td><td className="px-4 py-3">{formatVnd(row.amount)}</td><td className="px-4 py-3">{row.direction === 'INCOME' ? 'Thu' : row.direction === 'EXPENSE' ? 'Chi' : '—'}</td><td className="px-4 py-3">{classificationNames[row.classification] || 'Chờ rà soát'}{row.classificationSource === 'RULE' && <span className="mt-1 block text-[10px] text-emerald-700">{row.classificationReason} · {row.classificationConfidence}%</span>}</td><td className="px-4 py-3 text-amber-800">{row.duplicate ? 'Có thể trùng' : row.errors.join(', ') || 'Sẵn sàng nhập'}</td></tr>)}</tbody></table></div><div className="flex flex-col gap-3 border-t border-line p-4 sm:flex-row sm:items-center"><label className="flex-1 text-xs text-muted">Tài khoản nhận sao kê<select value={importAccountId} onChange={(event) => setImportAccountId(event.target.value)} className="mt-1.5 block w-full max-w-sm rounded-xl border border-line bg-white px-3 py-2.5 text-sm"><option value="">Chọn tài khoản</option>{accountOptions.map((option) => <option key={option.value} value={option.value}>{option.label}</option>)}</select></label><label className="flex items-center gap-2 text-xs text-muted"><input type="checkbox" checked={includeDuplicates} onChange={(event) => setIncludeDuplicates(event.target.checked)} />Vẫn nhập dòng bị đánh dấu trùng</label><Button variant="secondary" onClick={() => setPreview(null)}>Hủy</Button><Button onClick={() => void commitImport()} disabled={importBusy || !importAccountId}>{importBusy ? 'Đang nhập…' : 'Nhập dòng hợp lệ'}</Button></div></div></div>}
    {transferModal && <RecordModal title="Chuyển tiền nội bộ" fields={transferFields} onClose={() => setTransferModal(false)} onSubmit={transferMoney} busy={transferBusy} />}
  </>;
}

const quoteActions = (row: Row, role: string): Action[] => {
  if (['OWNER', 'ACCOUNTANT'].includes(role) && ['REJECTED', 'APPROVED', 'SENT'].includes(row.status || '')) return [{ label: 'Tạo phiên bản mới', action: 'revise', variant: 'secondary' }, ...(row.status === 'APPROVED' ? [{ label: 'Đã gửi khách', action: 'mark-sent' }] : row.status === 'SENT' ? [{ label: 'Khách đã chấp nhận', action: 'accept' }] : [])] as Action[];
  if (role === 'OWNER' && row.status === 'PENDING_APPROVAL') return [{ label: 'Duyệt', action: 'approve', variant: 'primary' }, { label: 'Từ chối', action: 'reject' }];
  if (role === 'ACCOUNTANT' && row.status === 'DRAFT') return [{ label: 'Gửi duyệt', action: 'submit-for-approval', variant: 'primary' }];
  if (['OWNER', 'ACCOUNTANT'].includes(role) && row.status === 'APPROVED') return [{ label: 'Đánh dấu đã gửi khách', action: 'mark-sent', variant: 'primary' }];
  if (['OWNER', 'ACCOUNTANT'].includes(role) && row.status === 'SENT') return [{ label: 'Khách đã chấp nhận', action: 'accept', variant: 'primary' }];
  if (['OWNER', 'ACCOUNTANT'].includes(role) && row.status === 'ACCEPTED' && !row.productionOrderId) return [{ label: 'Tạo lệnh sản xuất', action: 'create-production', variant: 'primary' }];
  return [];
};
const quoteFields: FieldDef[] = [
  { name: 'code', label: 'Mã báo giá', required: true, placeholder: 'BG-2026-020' }, { name: 'customerName', label: 'Khách hàng', required: true },
  { name: 'title', label: 'Sản phẩm / dịch vụ', required: true }, { name: 'date', label: 'Ngày lập', type: 'date', required: true },
  { name: 'validUntil', label: 'Hiệu lực đến', type: 'date' }, { name: 'quantity', label: 'Số lượng', type: 'number', min: 0.01 },
  { name: 'materialCost', label: 'Chi phí vật tư (₫)', type: 'number', min: 0 }, { name: 'laborHours', label: 'Giờ công', type: 'number', min: 0 },
  { name: 'laborRate', label: 'Chi phí/giờ công (₫)', type: 'number', min: 0 }, { name: 'machineCost', label: 'Điện/máy phân bổ (₫)', type: 'number', min: 0 },
  { name: 'wasteRate', label: 'Hao hụt dự kiến (%)', type: 'number', min: 0 }, { name: 'marginRate', label: 'Biên lợi nhuận mục tiêu (%)', type: 'number', min: 0 },
  { name: 'unitPrice', label: 'Đơn giá tùy chỉnh (₫, bỏ trống để gợi ý)', type: 'number', min: 0 }, { name: 'taxAmount', label: 'Tiền thuế nhập theo hồ sơ đã rà soát (₫)', type: 'number', min: 0 },
  { name: 'terms', label: 'Điều khoản / ghi chú', type: 'textarea', wide: true },
  { name: 'status', label: 'Trạng thái', type: 'select', options: [{ value: 'DRAFT', label: 'Bản nháp' }, { value: 'PENDING_APPROVAL', label: 'Chờ duyệt' }] },
];
const htmlText = (value: unknown) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char] || char));
function printQuotation(row: Row) {
  const printWindow = window.open('', '_blank');
  if (!printWindow) return false;
  const items = Array.isArray(row.items) ? row.items : [{ name: row.title, quantity: row.quantity, unitPrice: row.unitPrice, amount: row.subtotal }];
  const lineRows = items.map((item: Row) => `<tr><td>${htmlText(item.name || row.title)}</td><td>${htmlText(item.quantity ?? row.quantity ?? '')}</td><td>${htmlText(item.unit || '')}</td><td class="num">${formatVnd(item.unitPrice ?? row.unitPrice ?? 0)}</td><td class="num">${formatVnd(item.amount ?? row.subtotal ?? 0)}</td></tr>`).join('');
  printWindow.document.write(`<!doctype html><html lang="vi"><head><meta charset="utf-8"><title>${htmlText(row.code)} · Báo giá</title><style>@page{size:A4;margin:18mm}*{box-sizing:border-box}body{font:14px Arial,sans-serif;color:#252326;max-width:760px;margin:0 auto;padding:20px}header{display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid #9f201d;padding-bottom:18px}header img{width:210px;height:62px;object-fit:contain;object-position:left center}h1{font-size:24px;margin:28px 0 8px;color:#7d1d1b}.muted{color:#707078;font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:22px 0}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{padding:10px 8px;border-bottom:1px solid #e8e6e6;text-align:left}th{background:#f7f5f4;font-size:11px;text-transform:uppercase}.num{text-align:right;white-space:nowrap}.totals{width:300px;margin:18px 0 0 auto}.totals div{display:flex;justify-content:space-between;padding:6px 0}.grand{border-top:1px solid #aaa;font-weight:bold;font-size:17px}.terms{margin-top:32px;padding-top:16px;border-top:1px solid #e8e6e6;white-space:pre-wrap}.sign{display:flex;justify-content:space-between;margin-top:64px;text-align:center}.sign div{width:42%}@media print{body{padding:0}}</style></head><body><header><img src="${location.origin}/logo.png" alt="DichVuThue FinTax"><span class="muted">BẢN BÁO GIÁ</span></header><h1>Báo giá ${htmlText(row.code)}</h1><div class="grid"><div><b>Khách hàng</b><br>${htmlText(row.customerName)}<br>${htmlText(row.customerAddress || '')}</div><div><b>Ngày lập</b> ${formatDate(row.date)}<br><b>Hiệu lực đến</b> ${formatDate(row.validUntil)}</div></div><table><thead><tr><th>Sản phẩm / dịch vụ</th><th>SL</th><th>ĐVT</th><th class="num">Đơn giá</th><th class="num">Thành tiền</th></tr></thead><tbody>${lineRows}</tbody></table><div class="totals"><div><span>Tiền hàng</span><b>${formatVnd(row.subtotal || 0)}</b></div><div><span>Thuế theo thông tin nhập</span><b>${formatVnd(row.taxAmount || 0)}</b></div><div class="grand"><span>Tổng cộng</span><b>${formatVnd(row.total || 0)}</b></div></div>${row.terms ? `<div class="terms"><b>Điều khoản / ghi chú</b><br>${htmlText(row.terms)}</div>` : ''}<div class="sign"><div>ĐẠI DIỆN KHÁCH HÀNG</div><div>ĐẠI DIỆN XƯỞNG</div></div><script>window.onload=()=>setTimeout(()=>window.print(),250)</script></body></html>`);
  printWindow.document.close();
  return true;
}
function exportQuotation(row: Row) {
  const book = XLSX.utils.book_new();
  const summary = XLSX.utils.json_to_sheet([{ 'Mã báo giá': row.code, 'Khách hàng': row.customerName, 'Sản phẩm / dịch vụ': row.title, 'Ngày lập': row.date, 'Hiệu lực đến': row.validUntil, 'Số lượng': row.quantity, 'Giá vốn dự kiến': row.costEstimate, 'Đơn giá đề xuất': row.suggestedUnitPrice ?? row.unitPrice, 'Tiền hàng': row.subtotal, 'Thuế nhập theo hồ sơ': row.taxAmount, 'Tổng tiền': row.total, 'Trạng thái': statusLabel(row.status), 'Phiên bản': row.version || 1 }]);
  XLSX.utils.book_append_sheet(book, summary, 'Báo giá');
  const items = Array.isArray(row.items) ? row.items : [{ name: row.title, quantity: row.quantity, unitPrice: row.unitPrice, amount: row.subtotal }];
  XLSX.utils.book_append_sheet(book, XLSX.utils.json_to_sheet(items.map((item: Row) => ({ 'Sản phẩm / dịch vụ': item.name || row.title, 'Số lượng': item.quantity ?? row.quantity, 'Đơn vị': item.unit || '', 'Đơn giá': item.unitPrice ?? row.unitPrice, 'Thành tiền': item.amount ?? row.subtotal }))), 'Chi tiết');
  XLSX.utils.book_append_sheet(book, XLSX.utils.aoa_to_sheet([['CẤU THÀNH GIÁ DỰ KIẾN'], ['Vật tư', row.materialCost || 0], ['Nhân công', row.laborCost || 0], ['Điện/máy', row.machineCost || 0], ['Hao hụt', row.wasteRate || 0], ['Giá vốn ước tính', row.costEstimate || 0], ['Biên mục tiêu', row.marginRate || 0]]), 'Cấu thành giá');
  XLSX.writeFile(book, `${row.code || 'bao-gia'}.xlsx`);
}
export function QuotationsPage() {
  const toast = useToast();
  return <><ResourcePage entity="quotations" title="Báo giá & định mức" description="Tính giá thành theo vật tư, giờ công, máy móc và hao hụt; quản lý phiên bản và luồng duyệt." icon={<FileText size={18} />} columns={[{ key: 'code', label: 'Mã báo giá' }, { key: 'customerName', label: 'Khách hàng' }, { key: 'title', label: 'Sản phẩm / dịch vụ' }, { key: 'date', label: 'Ngày lập', format: 'date' }, { key: 'costEstimate', label: 'Giá vốn dự kiến', format: 'money' }, { key: 'total', label: 'Tổng báo giá', format: 'money' }, { key: 'status', label: 'Trạng thái', format: 'status' }]} fields={quoteFields} actions={quoteActions} rowExtra={(row) => <>{row.odooUrl ? <a href={row.odooUrl} target="_blank" rel="noreferrer" className="rounded-lg px-2 py-1 text-xs font-medium text-brand-700 hover:bg-brand-50">Mở báo giá Odoo</a> : row.syncStatus === 'PENDING_ODOO' ? <span className="px-2 py-1 text-xs text-muted">Đang đồng bộ Odoo…</span> : null}<Button variant="ghost" className="px-2 py-1 text-xs" onClick={() => exportQuotation(row)}>Excel</Button><Button variant="secondary" className="px-2 py-1 text-xs" onClick={() => { if (!printQuotation(row)) toast('Trình duyệt đã chặn cửa sổ in. Hãy cho phép cửa sổ bật lên rồi thử lại.', 'error'); }}>PDF / In</Button></>} /> </>;
}

const productionActions = (row:Row,role:string):Action[] => {
  if(row.status==='CANCELLED')return [];
  if(row.status==='READY_FOR_RECEIPT')return ['OWNER','ACCOUNTANT','WAREHOUSE'].includes(role)?[{label:'Nghiệm thu & Nhập thành phẩm',action:'receive-finished',variant:'primary'}]:[];
  if(row.status==='COMPLETED')return role==='OWNER'&&!row.finishedReceiptId?[{label:'Mở lại lệnh',action:'reopen'}]:[];
  if(role==='WAREHOUSE')return [];
  return row.status==='IN_PROGRESS'?[{label:'Kết thúc sản xuất',action:'complete',variant:'primary'}]:[{label:'Bắt đầu',action:'start',variant:'primary'}];
};
export function WorkshopPage() {
  const {user}=useAuth();const canWorkshop=(action:string)=>user?.permissions?.actions==='*'||user?.permissions?.actions?.includes(action);
  const materials = useRows('materials'); const toast = useToast(); const [selectedJob, setSelectedJob] = useState<Row | null>(null); const [laborJob, setLaborJob] = useState<Row | null>(null); const [progressJob, setProgressJob] = useState<Row | null>(null); const [refreshJobs, setRefreshJobs] = useState<(() => Promise<void>) | null>(null); const [busy, setBusy] = useState(false);
  const laborFields: FieldDef[] = [{ name: 'hours', label: 'Số giờ công', type: 'number', required: true, min: 0.1 }, { name: 'stage', label: 'Công đoạn', required: true }, { name: 'date', label: 'Ngày làm', type: 'date', required: true }, { name: 'note', label: 'Ghi chú công việc', type: 'textarea', wide: true }];
  const progressFields: FieldDef[] = [{ name: 'progress', label: 'Tiến độ (%)', type: 'number', required: true, min: 0, max: 100 }, { name: 'stage', label: 'Công đoạn hiện tại', required: true, wide: true }];
  const saveMovement = async (value: Record<string, unknown>) => {
    const material = materials.rows.find((row) => row.id === value.materialId);
    if (!material || !selectedJob) throw new Error('Không tìm thấy lệnh sản xuất hoặc vật tư.');
    setBusy(true);
    try { await createRecord('stock-movements', { ...value, code: `PX-${Date.now().toString().slice(-6)}`, materialName: material.name, productionOrderId: selectedJob.id, status: 'CONFIRMED' }); toast('Đã ghi nhận luân chuyển vật tư và cập nhật tồn kho.'); setSelectedJob(null); await Promise.all([materials.reload(), refreshJobs?.() || Promise.resolve()]); }
    catch (error) { throw new Error(messageOf(error)); }
    finally { setBusy(false); }
  };
  const saveLabor = async (value: Record<string, unknown>) => {
    if (!laborJob) throw new Error('Chọn lệnh sản xuất trước khi ghi giờ công.');
    setBusy(true);
    try { await createRecord('labor-logs', { ...value, productionOrderId: laborJob.id }); toast('Đã ghi giờ công vào lệnh sản xuất.'); setLaborJob(null); await refreshJobs?.(); }
    catch (error) { throw new Error(messageOf(error)); }
    finally { setBusy(false); }
  };
  const saveProgress = async (value: Record<string, unknown>) => {
    if (!progressJob) throw new Error('Chọn lệnh sản xuất trước khi cập nhật tiến độ.');
    setBusy(true);
    try { await actionRecord('production-orders', progressJob.id, 'progress', value); toast('Đã cập nhật công đoạn và tiến độ.'); setProgressJob(null); await refreshJobs?.(); }
    catch (error) { throw new Error(messageOf(error)); }
    finally { setBusy(false); }
  };
  return <><ResourcePage entity="production-orders" title="Lệnh sản xuất" description="Theo dõi lô sản xuất, công đoạn, tiến độ và ngày cần hoàn thành." icon={<Factory size={18} />} columns={[{ key: 'code', label: 'Mã lệnh' }, { key: 'productName', label: 'Sản phẩm' }, { key: 'customerName', label: 'Khách hàng' }, { key: 'stage', label: 'Công đoạn' }, { key: 'progress', label: 'Tiến độ' }, { key: 'dueDate', label: 'Hạn hoàn thành', format: 'date' }, { key: 'status', label: 'Trạng thái', format: 'status' }]} fields={[{ name: 'code', label: 'Mã lệnh', required: true }, { name: 'productId', label: 'Sản phẩm', required: true }, { name:'bomId',label:'Định mức'}, { name: 'customerName', label: 'Khách hàng' }, { name: 'quantity', label: 'Số lượng', type: 'number', min: 0.01,required:true }, {name:'laborRate',label:'Đơn giá giờ công (khi không có BOM)',type:'number',min:0}, { name: 'assignedTo', label: 'Người phụ trách' }, { name: 'stage', label: 'Công đoạn' }, { name: 'dueDate', label: 'Ngày cần xong', type: 'date' }, { name: 'status', label: 'Trạng thái', type: 'select', options: [{ value: 'IN_PROGRESS', label: 'Đang thực hiện' }, { value: 'DRAFT', label: 'Mới tạo' }] }]} actions={productionActions} rowExtra={(row, reload) => ['DRAFT','IN_PROGRESS'].includes(String(row.status||'')) ? <><Button variant="secondary" className="px-2.5 py-1.5 text-xs" onClick={() => { setSelectedJob(row); setRefreshJobs(() => reload); }}>Ghi vật tư</Button>{canWorkshop('record-labor')||canWorkshop('create')?<Button variant="ghost" className="px-2.5 py-1.5 text-xs" onClick={() => { setLaborJob(row); setRefreshJobs(() => reload); }}>Giờ công</Button>:null}{canWorkshop('progress')?<Button variant="ghost" className="px-2.5 py-1.5 text-xs" onClick={() => { setProgressJob(row); setRefreshJobs(() => reload); }}>Tiến độ</Button>:null}</> : null} emptyDescription="Tạo lệnh sản xuất đầu tiên hoặc nhận phân công từ chủ xưởng." />{selectedJob && <StockMovementModal initial={{productionOrderId:selectedJob.id,type:'ISSUE'}} onClose={()=>setSelectedJob(null)} onSubmit={saveMovement}/>}{laborJob && <RecordModal title={`Ghi giờ công · ${laborJob.code}`} fields={laborFields} onClose={() => setLaborJob(null)} onSubmit={saveLabor} busy={busy} />}{progressJob && <RecordModal title={`Cập nhật tiến độ · ${progressJob.code}`} fields={progressFields} onClose={() => setProgressJob(null)} onSubmit={saveProgress} busy={busy} />}</>;
}

export function InvoicesPage() {
  const [params,setParams] = useSearchParams();
  const [activeTab, setActiveTab] = useState<'INPUT' | 'OUTPUT'>(params.get('type') === 'INPUT' || params.get('direction') === 'INPUT' ? 'INPUT' : 'OUTPUT');
  useEffect(() => { if (params.get('type')) setActiveTab(params.get('type') === 'INPUT' ? 'INPUT' : 'OUTPUT'); },[params]);
  return <><div className="mb-5 flex gap-3">{(['OUTPUT', 'INPUT'] as const).map((type) => <Button key={type} variant={activeTab === type ? 'primary' : 'secondary'} onClick={() => { setActiveTab(type); setParams({type}); }}>{type === 'INPUT' ? 'Hóa đơn mua vào (Chi)' : 'Hóa đơn bán ra (Thu)'}</Button>)}</div><ResourcePage key={activeTab} fixedType={activeTab} entity="invoices" title={activeTab === 'INPUT' ? 'Hóa đơn mua vào' : 'Hóa đơn bán ra'} description="Tự tính thuế theo từng mặt hàng; theo dõi thanh toán và công nợ." icon={<FileCheck2 size={18}/>} columns={[{ key: 'code', label: 'Số hóa đơn' }, { key: 'direction', label: 'Loại', format: 'status' }, { key: 'counterparty', label: 'Đối tác' }, { key: 'date', label: 'Ngày', format: 'date' }, { key: 'subtotal', label: 'Tiền hàng', format: 'money' }, { key: 'taxAmount', label: 'Thuế', format: 'money' }, { key: 'total', label: 'Tổng tiền', format: 'money' }, { key: 'openBalance', label: 'Còn nợ', format: 'money' }, { key: 'paymentStatus', label: 'Thanh toán', format: 'status' }, { key: 'status', label: 'Trạng thái', format: 'status' }]} fields={[]} actions={(row) => row.direction === 'OUTPUT' && !['DEMO_CODE_ISSUED', 'CANCELLED'].includes(row.status || '') ? [{ label: 'Cấp mã CQT', action: 'simulate-code' }] : []} rowExtra={(row) => row.odooUrl ? <a href={row.odooUrl} target="_blank" rel="noreferrer">Mở Odoo</a> : null}/></>;
}
