export function CatalogPage() { const [tab, setTab] = useState<'products' | 'materials' | 'boms'>(new URLSearchParams(window.location.search).get('tab') === 'materials' ? 'materials' : 'products'); const pages = { products: { title: 'Sản phẩm', description: 'Danh mục thành phẩm và giá vốn tham chiếu.', fields: [{ name: 'code', label: 'Mã sản phẩm' }, { name: 'name', label: 'Tên sản phẩm', required: true }, { name: 'unit', label: 'Đơn vị tính',required:true }, {name:'trackInventory',label:'Quản lý tồn kho',type:'select' as const,options:[{value:'true',label:'Có quản lý tồn'},{value:'false',label:'Dịch vụ / Không quản lý tồn'}]}, { name: 'price', label: 'Giá bán tham chiếu (₫)', type: 'number' as const }, { name: 'cost', label: 'Giá vốn dự kiến (₫)', type: 'number' as const }] }, materials: { title: 'Vật tư', description: 'Tồn kho, định mức tối thiểu và đơn giá nhập.', fields: [{ name: 'code', label: 'Mã vật tư' }, { name: 'name', label: 'Tên vật tư', required: true }, { name: 'category', label: 'Nhóm vật tư' }, { name: 'unit', label: 'Đơn vị tính',required:true }, {name:'trackInventory',label:'Quản lý tồn kho',type:'select' as const,options:[{value:'true',label:'Có quản lý tồn'},{value:'false',label:'Dịch vụ / Không quản lý tồn'}]}, { name: 'minStock', label: 'Tồn tối thiểu', type: 'number' as const }, { name: 'unitCost', label: 'Đơn giá (₫)', type: 'number' as const }] }, boms: { title: 'Định mức BOM', description: 'Công thức vật tư, công lao động và phần phân bổ máy móc.', fields: [{ name: 'productName', label: 'Sản phẩm', required: true }, { name: 'version', label: 'Phiên bản', type: 'number' as const }, { name: 'materialCost', label: 'Chi phí vật tư (₫)', type: 'number' as const }, { name: 'laborHours', label: 'Giờ công', type: 'number' as const }, { name: 'laborRate', label: 'Đơn giá giờ công (₫)', type: 'number' as const }, { name: 'machineCost', label: 'Điện/máy phân bổ (₫)', type: 'number' as const }, { name: 'wasteRate', label: 'Tỷ lệ hao hụt (%)', type: 'number' as const }, { name: 'marginRate', label: 'Biên lợi nhuận mục tiêu (%)', type: 'number' as const }] } };
  const current = pages[tab];
  return <><div className="mb-5 flex gap-2 overflow-x-auto">{Object.entries(pages).map(([key, page]) => <button key={key} onClick={() => setTab(key as typeof tab)} className={`whitespace-nowrap rounded-xl px-4 py-2 text-sm font-medium ${tab === key ? 'bg-brand-600 text-white' : 'border border-line bg-white text-muted hover:text-ink'}`}>{page.title}</button>)}</div><ResourcePage key={tab} entity={tab} title={current.title} description={current.description} icon={<Package size={18} />} fields={tab === 'boms' ? current.fields : [...current.fields, { name: 'inputTaxRate', label: 'Thuế suất đầu vào (%)', type: 'number', min: 0, max: 100 }, { name: 'outputTaxRate', label: 'Thuế suất đầu ra (%)', type: 'number', min: 0, max: 100 }]} columns={(tab === 'products' ? [{ key: 'code', label: 'Mã' }, { key: 'name', label: 'Sản phẩm' }, { key: 'unit', label: 'Đơn vị' }, { key: 'cost', label: 'Giá vốn', format: 'money' }, { key: 'price', label: 'Giá bán', format: 'money' }] : tab === 'materials' ? [{ key: 'code', label: 'Mã vật tư' }, { key: 'name', label: 'Vật tư' }, { key: 'category', label: 'Nhóm' }, { key: 'stock', label: 'Tồn kho' }, { key: 'minStock', label: 'Tối thiểu' }, { key: 'unitCost', label: 'Đơn giá', format: 'money' }] : [{ key: 'productName', label: 'Sản phẩm' }, { key: 'version', label: 'Phiên bản' }, { key: 'materialCost', label: 'Vật tư', format: 'money' }, { key: 'laborCost', label: 'Chi phí công', format: 'money' }, { key: 'machineCost', label: 'Điện/máy', format: 'money' }, { key: 'estimatedUnitCost', label: 'Giá vốn ước tính', format: 'money' }, { key: 'suggestedPrice', label: 'Giá bán gợi ý', format: 'money' }, { key: 'status', label: 'Trạng thái', format: 'status' }]) as Column[]} /> </>;
}

export function ReconciliationPage() { const [allocationOpen, setAllocationOpen] = useState(false); return <><ResourcePage entity="reconciliations" title="Đối soát & công nợ" description="So sánh hóa đơn, thanh toán và sao kê; xác nhận từng trường hợp có giải thích." icon={<ClipboardCheck size={18} />} toolbar={<Button variant="secondary" onClick={() => setAllocationOpen(true)}>Phân bổ / Xử lý chênh lệch</Button>} columns={[{ key: 'code', label: 'Mã đối soát' }, { key: 'counterparty', label: 'Đối tượng' }, { key: 'period', label: 'Kỳ' }, { key: 'invoiceAmount', label: 'Giá trị hóa đơn', format: 'money' }, { key: 'paymentAmount', label: 'Tiền đã nhận/chi', format: 'money' }, { key: 'status', label: 'Kết quả', format: 'status' }, { key: 'note', label: 'Ghi chú' }]} fields={[{ name: 'invoiceId', label: 'ID hóa đơn (nếu đối soát hóa đơn)' }, { name: 'paymentId', label: 'ID phiếu thu / chi' }, { name: 'date', label: 'Ngày hạch toán', type: 'date', required: true }, { name: 'code', label: 'Mã đối soát' }, { name: 'counterparty', label: 'Đối tượng', required: true }, { name: 'period', label: 'Kỳ đối soát', required: true }, { name: 'invoiceAmount', label: 'Giá trị hóa đơn (₫)', type: 'number' }, { name: 'paymentAmount', label: 'Giá trị thanh toán (₫)', type: 'number' }, { name: 'status', label: 'Trạng thái', type: 'select', options: [{ value: 'MATCHED', label: 'Khớp' }, { value: 'PARTIAL', label: 'Khớp một phần' }, { value: 'MISMATCH', label: 'Lệch' }, { value: 'UNRESOLVED', label: 'Chưa đối soát' }] }, { name: 'note', label: 'Ghi chú rà soát', type: 'textarea', wide: true }]} actions={(row, role) => row.status === 'MATCHED' ? role === 'OWNER' ? [{ label: 'Mở lại', action: 'reopen' }] : [] : role !== 'WORKSHOP' ? [{ label: 'Xác nhận', action: 'confirm', variant: 'primary' }] : []} />{allocationOpen && <AllocationModal onClose={() => setAllocationOpen(false)} onSaved={async () => { window.dispatchEvent(new Event('fintax:records-changed')); }}/>}</>; }

