  const [fxBusy,setFxBusy]=useState(false);
  const provisionErp=async()=>{setFxBusy(true);try{const {data}=await api.post('/integrations/odoo/company');toast(data.message||'Đã liên kết công ty Odoo.');await loadTab();}catch(error){toast(messageOf(error),'error');}finally{setFxBusy(false);}};
  const [searchParams] = useSearchParams(); const [tab, setTab] = useState<'profile' | 'accounts' | 'users' | 'permissions' | 'rules' | 'classifications' | 'integrations' | 'audit'>(() => (['profile','accounts','users','permissions','rules','classifications','integrations','audit'].includes(searchParams.get('tab') || '') ? searchParams.get('tab') : 'profile') as any); const [users, setUsers] = useState<any[]>([]); const [rolePermissions, setRolePermissions] = useState<any[]>([]); const [logs, setLogs] = useState<any[]>([]); const [integrations, setIntegrations] = useState<any>(null); const [queueRows, setQueueRows] = useState<any[]>([]); const [syncing, setSyncing] = useState(false); const [modal, setModal] = useState(false); const [passwordModal, setPasswordModal] = useState(false); const [loading, setLoading] = useState(false); const toast = useToast(); const { user } = useAuth();
  const loadTab = useCallback(async () => { setLoading(true); try { if (tab === 'users' && user?.role === 'OWNER') setUsers((await api.get('/users')).data); if (tab === 'permissions' && user?.role === 'OWNER') setRolePermissions((await api.get('/role-permissions')).data); if (tab === 'audit' && user?.role === 'OWNER') setLogs((await api.get('/audit-logs')).data); if (tab === 'integrations') { setIntegrations((await api.get('/integrations/status')).data); if (user?.role === 'OWNER') setQueueRows((await api.get('/integrations/odoo/queue')).data); } } catch (error) { toast(messageOf(error), 'error'); } finally { setLoading(false); } }, [tab, user?.role]);
  useEffect(() => { void loadTab(); }, [loadTab]);
