  const saveItem = async (value: Record<string, unknown>) => { try { if (tab === 'users') await api.post('/users', value); else if (tab === 'rules') await createRecord('tax-rules', value); setModal(false); toast('Đã lưu thông tin.'); await loadTab(); } catch (error) { throw new Error(messageOf(error)); } };
  const setUserActive = async (id: string, active: boolean) => { try { await api.patch(`/users/${id}/status`, { active }); toast(active ? 'Đã mở tài khoản.' : 'Đã khóa tài khoản.'); await loadTab(); } catch (error) { toast(messageOf(error), 'error'); } };
  const refreshFx=async()=>{setFxBusy(true);try{await api.post('/integrations/odoo/currency/refresh');await loadTab();toast('Đã cập nhật tỷ giá VND theo nguồn công bố.');}catch(error){toast(messageOf(error),'error');}finally{setFxBusy(false);}};
  const syncPending = async () => { setSyncing(true); try { const { data: backfill } = await api.post('/integrations/odoo/enqueue-unsynced'); const { data } = await api.post('/integrations/odoo/sync-pending'); const synced = data.results.filter((item: any) => item.status === 'SYNCED').length; const pending = data.results.length - synced; toast(`Đã đồng bộ ${synced}/${data.attempted} bản ghi; đưa thêm ${backfill.queued} mục cũ vào hàng đợi${pending ? `; ${pending} mục chờ xử lý` : ''}.`, pending ? 'info' : 'success'); await loadTab(); } catch (error) { toast(messageOf(error), 'error'); } finally { setSyncing(false); } };
